pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 value) internal {
        try c.SetMinSum(value) {} catch { return; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(afterFirst == value && c.MinSum() == value && reverted);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
